NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'II Thessalonians'

CHAPTERS = {
    1: {
        1: 'Paulus und Silvanus und Timotheus an die Gemeinde der Thessalonicher in Gott unserem Vater und Herrn Jesus Christus.',
        2: 'Gnade sei mit euch und Friede von Gott unserem Vater und unserem Herrn Jesus Christus.',
        3: 'Danken müssen wir Gott allezeit um euch, liebe Brüder, wie es sich gebührt, daß euer Glauben immer mehr zunimmt, und die Liebe eines jeglichen unter euch allen gegeneinander wächst,',
        4: 'Also daß wir uns euer rühmen in den Gemeinden Gottes über eurer Beharrlichkeit und eurem Glauben, in allen euren Verfolgungen und Trübsalen, die ihr erduldet;',
        5: 'Was anzeigt, daß Gott gerecht richtet, so daß ihr würdig werdet des Reiches Gottes, über dem ihr auch leidet.',
        6: 'Zumal es gerecht ist vor Gott, daß Er denen, die euch Trübsal bereiten, Trübsal vergelte;',
        7: 'Und euch, die ihr bedrängt werdet, Ruhe mit uns, bei der Offenbarung des Herrn Jesus vom Himmel mit den Engeln Seiner Kraft,',
        8: 'In Feuerflammen, Rache nehmend an denen, so Gott nicht erkennen, und die nicht dem Evangelium unseres Herrn Jesus Christus Gehorsam leisten;',
        9: 'Welche die Strafe erleiden, ewiges Elend von dem Angesichte des Herrn und der Herrlichkeit Seiner Macht,',
        10: 'Wenn Er kommen wird, um in Seinen Heiligen verherrlicht und in allen Gläubigen',
        11: 'Darum beten wir auch allezeit für euch, daß unser Gott euch würdig erachte der Berufung, und jedwedes Wohlgefallen am Guten und das Werk des Glaubens mit Kraft zur Erfüllung bringe;',
        12: 'Auf daß der Name unseres Herrn Jesus Christus in euch verherrlicht werde, und ihr in Ihm, nach der Gnade unseres Gottes und Herrn Jesus Christus.',
    },
    2: {
        1: 'Wir bitten euch aber, Brüder, in betreff der Wiederkunft unseres Herrn Jesus Christus und unserer Hinführung zu Ihm,',
        2: 'Daß ihr euch nicht sogleich abwenden lasset aus eurer Gesinnung, noch beunruhigen durch einen Geist, noch durch Wort, noch durch Schreiben, als von uns kommend, als ob der Tag des Herrn nahe bevorstehe.',
        3: 'Laßt euch von niemand irgendwie verführen; denn erst muß der Abfall kommen, und der Mensch der Sünde, der Sohn des Verderbens, offenbar werden,',
        4: 'Welcher sich auflehnt und erhebt über alles, was Gott und Anbetung heißt, und sich als Gott in den Tempel Gottes setzt und sich selbst für Gott erklärt.',
        5: 'Gedenkt ihr noch, daß ich euch solches sagte, als ich noch bei euch war?',
        6: 'Auch wißt ihr, was es noch aufhält, daß Er in Seiner Zeit Sich offenbart.',
        7: 'Denn das Geheimnis der Ruchlosigkeit ist schon in Wirksamkeit, bis nur erst der, so es aufhält, aus dem Wege ist,',
        8: 'Und dann wird der Ruchlose offenbar werden, den der Herr mit dem Hauche Seines Mundes vertilgen und durch die Erscheinung Seiner Gegenwart zunichte machen wird.',
        9: 'Seine Ankunft aber geschieht nach der Wirksamkeit des Satans in allerlei Lügenkraft, in Zeichen und Wundern,',
        10: 'Und mit allerlei Verführung zur Ungerechtigkeit unter den Verlorenen, dafür, daß sie die Liebe zur Wahrheit nicht aufkommen ließen, auf daß sie gerettet würden.',
        11: 'Und darum wird Gott über sie die Kraft der Verführung kommen lassen, so daß sie der Lüge glauben;',
        12: 'Auf daß gerichtet werden alle, die nicht an die Wahrheit glaubten, sondern an der Ungerechtigkeit Wohlgefallen hatten.',
        13: 'Wir aber müssen allezeit Gott danken für euch, Brüder, die ihr vom Herrn geliebt seid, daß euch Gott von Anfang an durch die Heiligung des Geistes zur Seligkeit auserwählt hat.',
        14: 'Wozu Er euch berufen hat durch unser Evangelium, auf daß ihr zur Herrlichkeit unseres Herrn Jesus Christus gelangen könnt.',
        15: 'So steht nun fest, Brüder, und haltet an den Überlieferungen, die ihr durch unser Wort oder durch Briefe gelehrt worden seid.',
        16: 'Er aber, unser Herr Jesus Christus und Gott und unser Vater, Der uns geliebt und ewigen Beistand und gute Hoffnung nach Seiner Gnade verliehen hat,',
        17: 'Der tröste eure Herzen und befestige euch in jeglichem guten Wort und Werk.',
    },
    3: {
        1: 'Weiter, Brüder, betet für uns, daß das Wort des Herrn sich verbreite und verherrlicht werde, so wie bei euch;',
        2: 'Und daß wir erlöst werden von den mißliebigen und argen Menschen; denn der Glaube ist nicht jedermanns Ding.',
        3: 'Der Herr aber ist treu, Der wird euch stärken und bewahren vor dem Argen.',
        4: 'Wir haben im Herrn das Vertrauen zu euch, daß ihr, was wir euch anbefehlen, auch tut und tun werdet.',
        5: 'Der Herr aber lenke eure Herzen zur Liebe Gottes und zur Beharrlichkeit in Christus.',
        6: 'Wir anempfehlen euch aber, Brüder, im Namen des Herrn Jesus Christus, daß ihr euch von jeglichem Bruder zurückzieht, der unordentlich und nicht nach der Vorschrift lebt, die er von uns empfangen hat.',
        7: 'Ihr wißt ja selbst, wie ihr uns nachleben sollt, denn wir haben unter euch nicht unordentlich gelebt;',
        8: 'Auch haben wir nicht jemandes Brot umsonst gegessen, sondern mit Mühe und Beschwerde Tag und Nacht gearbeitet, um keinem unter euch beschwerlich zu werden;',
        9: 'Nicht als ob wir dazu kein Recht gehabt hätten, sondern um euch ein Vorbild zu geben, daß ihr uns nachleben sollt.',
        10: 'Denn als wir bei euch waren, stellten wir auf, daß einer, der nicht arbeiten will, auch nicht essen soll;',
        11: 'Weil wir hören, daß etliche unter euch unordentlich wandeln, nicht arbeiten, sondern unnütze Dinge treiben.',
        12: 'Solchen aber anempfehlen wir und vermahnen sie durch unseren Herrn Jesus Christus, daß sie geruhig arbeiten und ihr eigenes Brot essen.',
        13: 'Ihr aber, Brüder, seid unverdrossen im Gutestun.',
        14: 'So aber jemand sich an unser Wort in dem Brief nicht kehrt, den zeichnet an, und habt keine Gemeinschaft mit ihm, daß er sich schämen muß.',
        15: 'Doch haltet ihn nicht als Feind, sondern vermahnt ihn als einen Bruder.',
        16: 'Er aber, der Herr des Friedens, gebe euch allezeit und allenthalben Frieden, der Herr sei mit euch allen.',
        17: 'Der Gruß ist von meiner, Paulus eigener Hand, und ist euch das Zeichen in allen Briefen. Also schreibe ich:',
        18: 'Die Gnade unseres Herrn Jesus Christi sei mit euch allen. Amen.',
    },
}
